    const state = uiBattleState([battlePlayer(0)], [battleEnemy(spriteEnemy(50))], {
      uiState: 'wait',
      turn: 1,
      selectionStartedForTurn: undefined,
    })
    drawBattleUI(fb, state, playerRoles, [], [], uiGameState(), undefined, UI)
